package com.tihai.controller;
import com.tihai.utils.*;import org.springframework.web.bind.annotation.ControllerAdvice;import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdviceAdapter;import org.springframework.core.MethodParameter;import org.springframework.http.*;import org.springframework.http.converter.HttpMessageConverter;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.context.request.*;import java.lang.reflect.Type;import java.util.*;
@ControllerAdvice public class ScopeBodyAdvice extends RequestBodyAdviceAdapter {
 @Autowired AccountRegistry registry;
 public boolean supports(MethodParameter p,Type t,Class<? extends HttpMessageConverter<?>> c){return true;}
 public Object afterBodyRead(Object b,HttpInputMessage in,MethodParameter p,Type t,Class<? extends HttpMessageConverter<?>> c){if(!AccountScope.scoped())return b;String path=((ServletRequestAttributes)RequestContextHolder.currentRequestAttributes()).getRequest().getRequestURI();if(b instanceof Map){Map m=(Map)b;String id=String.valueOf(m.get("id"));if(path.startsWith("/local/assessments/"))registry.requireResource("assessment",id);if(path.startsWith("/local/exams/"))registry.requireResource("exam",id);if(path.matches("/local/signin/(start|stop|recheck)"))registry.requireResource("signin",id);if(path.startsWith("/local/review/"))registry.requireTask(String.valueOf(m.get("course")));}if(b instanceof com.tihai.dubbo.dto.CourseSubmitTaskDTO)AccountScope.require(((com.tihai.dubbo.dto.CourseSubmitTaskDTO)b).getLoginAccount());return b;}
}
